-- GENERATED by db/gen_grants.py from db/allowlist.yaml. Do not edit by hand.
-- Runs once at container init, as postgres, connected to the pagila DB.

-- reader: the only role the pipeline executes guarded SQL with
CREATE ROLE sqlguard_reader LOGIN PASSWORD 'reader_pw'
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT CONNECTION LIMIT 10;
ALTER ROLE sqlguard_reader SET default_transaction_read_only = on;
ALTER ROLE sqlguard_reader SET statement_timeout = '5s';
ALTER ROLE sqlguard_reader SET idle_in_transaction_session_timeout = '10s';
ALTER ROLE sqlguard_reader SET search_path = public;   -- no schema shadowing

REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO sqlguard_reader;

-- column-level grants (allowlisted columns only; restricted columns are never granted)
GRANT SELECT (actor_id, first_name, last_name) ON actor TO sqlguard_reader;
GRANT SELECT (film_id, title, description, release_year, language_id, rental_duration, rental_rate, length, replacement_cost, rating, special_features) ON film TO sqlguard_reader;
GRANT SELECT (actor_id, film_id) ON film_actor TO sqlguard_reader;
GRANT SELECT (category_id, name) ON category TO sqlguard_reader;
GRANT SELECT (film_id, category_id) ON film_category TO sqlguard_reader;
GRANT SELECT (language_id, name) ON language TO sqlguard_reader;
GRANT SELECT (inventory_id, film_id, store_id) ON inventory TO sqlguard_reader;
GRANT SELECT (rental_id, rental_date, inventory_id, customer_id, return_date, staff_id) ON rental TO sqlguard_reader;
GRANT SELECT (payment_id, customer_id, staff_id, rental_id, amount, payment_date) ON payment TO sqlguard_reader;
GRANT SELECT (customer_id, store_id, first_name, last_name, active, create_date, address_id) ON customer TO sqlguard_reader;
GRANT SELECT (address_id, address, district, city_id, postal_code) ON address TO sqlguard_reader;
GRANT SELECT (city_id, city, country_id) ON city TO sqlguard_reader;
GRANT SELECT (country_id, country) ON country TO sqlguard_reader;
GRANT SELECT (store_id, manager_staff_id, address_id) ON store TO sqlguard_reader;
GRANT SELECT (staff_id, first_name, last_name, store_id, active) ON staff TO sqlguard_reader;

-- block dangerous functions (AST_CHECK allowlist is the main control; this is the backstop)
REVOKE EXECUTE ON FUNCTION pg_sleep(double precision) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION pg_sleep_for(interval) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION pg_sleep_until(timestamptz) FROM PUBLIC;
REVOKE EXECUTE ON ALL ROUTINES IN SCHEMA public FROM PUBLIC;   -- film_in_stock, rewards_report, ...

-- app role: only its own DB
CREATE ROLE sqlguard_app LOGIN PASSWORD 'app_pw';
CREATE DATABASE sqlguard_app OWNER sqlguard_app;

-- each role may connect only to its own DB (pg_sleep is still executable in the others)
REVOKE CONNECT ON DATABASE pagila, sqlguard_app, postgres FROM PUBLIC;
GRANT CONNECT ON DATABASE pagila TO sqlguard_reader;
GRANT CONNECT ON DATABASE sqlguard_app TO sqlguard_app;
